#include <stdio.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void) {
    pid_t hijo = fork();
    if (hijo == 0) {
        __asm__ volatile("cli");        /* intenta apagar las interrupciones desde modo usuario */
        printf("cli ejecutada sin problema\n");
        return 0;
    }
    int estado;
    waitpid(hijo, &estado, 0);
    if (WIFSIGNALED(estado))
        printf("el hijo murio por la senal %d (%s)\n", WTERMSIG(estado), strsignal(WTERMSIG(estado)));
    else
        printf("el hijo termino normalmente\n");
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

static double now(clockid_t c) {
    struct timespec t;
    clock_gettime(c, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

int main(int argc, char **argv) {
    double fin = now(CLOCK_MONOTONIC) + 3.0;   /* gira 3 segundos de reloj */
    volatile unsigned long vueltas = 0;
    while (now(CLOCK_MONOTONIC) < fin)
        vueltas++;                              /* bucle sin llamadas que bloqueen */
    char linea[128];
    FILE *f = fopen("/proc/self/status", "r");
    long invol = -1;
    while (fgets(linea, sizeof linea, f))
        if (sscanf(linea, "nonvoluntary_ctxt_switches: %ld", &invol) == 1) break;
    fclose(f);
    printf("%s: CPU usada %.2f s de 3.00 s de reloj, expropiado %ld veces\n",
           argv[1], now(CLOCK_PROCESS_CPUTIME_ID), invol);
    return 0;
}
